INSERT INTO `demandes_vendeur` (`id`, `id_uti`, `nom_boutique`, `description`, `categorie`, `telephone`, `image_boutique`, `adresse`, `pays`, `statut`, `date_demande`) VALUES
(1, 1, 'NDIGIT MARKET', 'Découvrez des templates premium, designs créatifs et ressources web conçus pour donner vie à vos projets avec qualité et innovation.', 'applications', '2290198111986', 'uploads/boutique_6a0457c24794a.png', 'Cotonou', 'Bénin', 'acceptee', '2026-05-07 18:25:40'),
(2, 3, 'Nawane Sanny', 'Développeur web proposant des templates, codes sources et interfaces modernes prêts à l’emploi pour accélérer vos projets digitaux.', 'applications', '2290191736598', 'uploads/boutique_6a06da9adf890.png', 'Quartier Danto', 'Bénin', 'acceptee', '2026-05-07 18:57:46'),
(4, 176, 'Pyruxshop', 'Transformez vos idées en projets professionnels avec des templates React modernes, rapides et prêts à l’emploi.\r\n\r\nDans notre boutique, vous trouverez des interfaces haut de gamme conçues pour les développeurs, startups, agences et entrepreneurs qui veulent lancer leurs projets plus vite et avec un design professionnel.\r\n\r\n✨ Ce que nous proposons :\r\n• Templates React modernes et responsive\r\n• Dashboards Admin professionnels\r\n• Landing pages ultra-convertissantes\r\n• UI Kits élégants et optimisés\r\n• Templates SaaS et e-commerce\r\n• Codes propres, rapides et faciles à personnaliser\r\n• Compatibilité Vite, Tailwind CSS, TypeScript et technologies modernes\r\n\r\n???? Pourquoi choisir nos produits ?\r\n✔ Design premium et moderne\r\n✔ Gain de temps énorme pour vos projets\r\n✔ Code optimisé et structuré\r\n✔ Installation simple et rapide\r\n✔ Expérience utilisateur professionnelle\r\n✔ Idéal pour freelances, agences et startups\r\n\r\nQue vous créiez une application, une boutique en ligne, une plateforme SaaS ou un site vitrine, nos templates vous permettent de démarrer immédiatement avec une base solide et professionnelle.\r\n\r\n???? Créez plus vite. Vendez mieux. Impressionnez vos clients.', 'autre', '2290149997071', 'uploads/boutique_6a0c813eae7bc.png', '', 'Bénin', 'acceptee', '2026-05-11 17:56:42'),
(6, 178, 'Laura Web Studio', 'Je crée des templates web premium modernes, élégants et prêts à l’emploi pour différents domaines d’activité.\r\n\r\nMes créations sont conçues pour aider les entreprises, marques et entrepreneurs à avoir une présence en ligne moderne, professionnelle et attractive.\r\n\r\nJe propose des templates pour :\r\n• salons de beauté\r\n• pédicure & manucure\r\n• voyage & tourisme\r\n• cosmétique\r\n• restaurants\r\n• agences\r\n• e-commerce\r\n• portfolios\r\n• coaching\r\n• et bien d’autres domaines.\r\n\r\nChaque template est réalisé avec soin pour offrir un design fluide, esthétique, responsive et facile à personnaliser.\r\n\r\nMon objectif :\r\nCréer des designs modernes qui attirent l’attention, valorisent les projets et donnent une image professionnelle aux marques.', 'autre', '2290150824534', '', '', 'Bénin', 'acceptee', '2026-05-13 11:58:59'),
(8, 129, 'MK Digit', 'Bienvenue chez MK Digit ????\r\n\r\nMK Digit est une boutique digitale spécialisée dans la création et la vente de templates modernes, professionnels et 100% responsive. Notre objectif est d’aider les développeurs, startups, entreprises et créateurs africains à lancer rapidement des projets web élégants et performants.', 'autre', '2290159158624', '', '', 'Bénin', 'acceptee', '2026-05-19 18:51:00'),
(10, 185, 'Cherias Dev Solutions', 'Développement de sites web, applications et solutions digitales modernes pour particuliers et entreprises.', 'autre', '2290151033466', 'uploads/boutique_6a0c95451c82c.jpg', '', 'Bénin', 'acceptee', '2026-05-19 18:52:21');
